import FreeCAD
import Part

# Open the precondition file with more detailed inspection
doc = FreeCAD.open('/home/user/Precondition_Unnamed.FCStd')

# Check all possible ways to find sketches
print("=== Document Inspection ===")
print(f"Document Name: {doc.Name}")
print(f"Root Objects: {[o.Name for o in doc.RootObjects]}")
print(f"All Objects: {[o.Name for o in doc.Objects]}")

# Check for any Link objects or groups
for obj in doc.Objects:
    print(f"\n--- Object: {obj.Name} ---")
    print(f"  TypeId: {obj.TypeId}")
    print(f"  Label: {obj.Label}")

    # Check for Support property (often used in sketches)
    if hasattr(obj, 'Support'):
        print(f"  Support: {obj.Support}")

    # Check for Geometry property
    if hasattr(obj, 'Geometry'):
        print(f"  Geometry count: {len(obj.Geometry)}")

    # Check for Shape
    if hasattr(obj, 'Shape'):
        shape = obj.Shape
        print(f"  Shape Type: {shape.ShapeType}")

        # Look for wires
        for i, wire in enumerate(shape.Wires):
            print(f"  Wire {i}: Length={wire.Length}, Closed={wire.isClosed()}")
            if wire.isClosed():
                # Try to compute the area of the wire's projection
                try:
                    face = Part.Face(wire)
                    print(f"    Face area: {face.Area}")
                except Exception as e:
                    print(f"    Cannot create face: {e}")

# Let's also check the document's internal structure
print("\n=== Checking for hidden or embedded objects ===")
# Try to access any potential sketch data
for obj in doc.Objects:
